import type { MockConfig, ApiResponse } from '../../types'
import type { UserLoginVO, UserVO } from '@/api/login/types'

/**
 * 登录响应数据
 */
interface LoginResponse {
  userId: number
  accessToken: string
  refreshToken: string
  expiresTime: number
}

/**
 * 权限信息响应
 */
interface PermissionInfo {
  user: UserVO
  roles: string[]
  permissions: string[]
  menus: any[]
}

/**
 * 验证码响应
 */
interface CaptchaResponse {
  uuid: string
  img: string
}

// Mock 用户数据
const mockUser: UserVO = {
  id: 1,
  username: 'admin',
  nickname: '芋道源码',
  deptId: 103,
  email: '11aoteman@126.com',
  mobile: '15888888888',
  sex: 1,
  avatar: 'http://test.governance.iocoder.cn/test/20250502/avatar_1746154660449.png',
  loginIp: '127.0.0.1',
  loginDate: new Date().toISOString()
}

const mockConfigs: MockConfig[] = [
  // 用户登录
  {
    url: '/admin-api/system/auth/login',
    type: 'post',
    response: ({ body }: { body: UserLoginVO }): ApiResponse<LoginResponse> => {
      const { username, password } = body

      // 简单的模拟验证
      if (username === 'admin' && password === 'admin123') {
        return {
          code: 0,
          data: {
            userId: 1,
            accessToken: 'mock-access-token-' + Date.now(),
            refreshToken: 'mock-refresh-token-' + Date.now(),
            expiresTime: Date.now() + 24 * 60 * 60 * 1000 // 24小时后过期
          },
          msg: '登录成功'
        }
      }

      return {
        code: 500,
        data: undefined as any,
        msg: '用户名或密码错误'
      }
    }
  },

  // 获取用户权限信息
  {
    url: '/admin-api/system/auth/get-permission-info',
    type: 'get',
    response: (): ApiResponse<PermissionInfo> => ({
      code: 0,
      data: {
        user: mockUser,
        roles: ['super_admin'],
        permissions: [
          'system:user:list',
          'system:user:create',
          'system:user:update',
          'system:user:delete',
          'system:dict:create',
          'system:dict:delete',
          'system:dict:query',
          'system:dict:export',
          'system:dict:update'
        ],
        menus: [] // 菜单数据在 menu.ts 中单独处理
      },
      msg: ''
    })
  },

  // 刷新访问令牌
  {
    url: '/admin-api/system/auth/refresh-token',
    type: 'post',
    response: ({ query }): ApiResponse<LoginResponse | null> => {
      const { refreshToken } = query || {}

      // 简单校验：必须是以 mock 刷新令牌开头
      if (!refreshToken || !String(refreshToken).startsWith('mock-refresh-token-')) {
        return {
          code: 401,
          data: null,
          msg: '无效的刷新令牌'
        }
      }

      return {
        code: 200,
        data: {
          userId: 1,
          accessToken: 'mock-access-token-' + Date.now(),
          refreshToken: 'mock-refresh-token-' + Date.now(),
          expiresTime: Date.now() + 24 * 60 * 60 * 1000 // 24小时后过期
        },
        msg: '刷新成功'
      }
    }
  },

  // 获取验证码
  {
    url: '/admin-api/system/captcha/get',
    type: 'get',
    response: (): ApiResponse<CaptchaResponse> => ({
      code: 0,
      data: {
        uuid: 'mock-captcha-uuid-' + Date.now(),
        img: 'data:image/png;base64,'
      },
      msg: ''
    })
  },

  // 用户登出
  {
    url: '/admin-api/system/auth/logout',
    type: 'post',
    response: (): ApiResponse<null> => ({
      code: 0,
      data: null,
      msg: '退出成功'
    })
  }
]

export default mockConfigs